///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = async function () {
    /* sdd-asis-lifecycle:begin fn_List — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_listForm.action = "/filing/editClass.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "findEditMidclasses");
    $c.util.getComponent('txt_listDiv').setValue(await scwin.tx_fn_List_xhr());
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.popInsert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.popInsert = async function () {
    /* sdd-asis-lifecycle:begin fn_PopInsert — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/editClass.do?method=prepareUpdateEditMidclass&upEditClssCd=" + dma_editUpclass.get("editClssCd") + "&mode=create";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "midclassPop", popupName: "midclassPop" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.popModify
 * @author Inswave
 * @date 2026. 09. 29
 * @param editClssCd
 * @returns
 * @hidden N
*/
scwin.popModify = async function (editClssCd) {
    /* sdd-asis-lifecycle:begin fn_PopModify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/editClass.do?method=prepareUpdateEditMidclass&editClssCd=" + editClssCd + "&upEditClssCd=" + dma_editUpclass.get("editClssCd") + "&mode=update";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "midclassPop", popupName: "midclassPop", width: "500", height: "340" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteListXhrReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param editClssCd editClssNm
 * @returns
 * @hidden N
*/
scwin.deleteListXhrReq = async function (editClssCd, editClssNm) {
    /* sdd-asis-lifecycle:begin fn_Delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _confirm = await $c.win.confirm("편집기중분류 '" + editClssNm + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_ListXhrReq').set('editClssCd', editClssCd);
    scwin.form_listForm.action = "/filing/editClass.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "deleteEditMidclass");
    $c.util.getComponent('txt_listDiv').setValue(await scwin.tx_fn_Delete_xhr());
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.up
 * @author Inswave
 * @date 2026. 09. 29
 * @param editClssCd screnDpOrdNo
 * @returns
 * @hidden N
*/
scwin.up = async function (editClssCd, screnDpOrdNo) {
    /* sdd-asis-lifecycle:begin fn_Up — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_ListXhrReq').set('editClssCd', editClssCd);
    $c.util.getComponent('dma_ListXhrReq').set('screnDpOrdNo', screnDpOrdNo);
    $c.util.getComponent('dma_ListXhrReq').set('direction', "up");
    $c.util.getComponent('dma_ListXhrReq').set('method', "updateEditClassOrdNo");
    $c.util.getComponent('txt_listDiv').setValue(await scwin.tx_fn_Up_xhr());
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.down
 * @author Inswave
 * @date 2026. 09. 29
 * @param editClssCd screnDpOrdNo
 * @returns
 * @hidden N
*/
scwin.down = async function (editClssCd, screnDpOrdNo) {
    /* sdd-asis-lifecycle:begin fn_Down — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_ListXhrReq').set('editClssCd', editClssCd);
    $c.util.getComponent('dma_ListXhrReq').set('screnDpOrdNo', screnDpOrdNo);
    $c.util.getComponent('dma_ListXhrReq').set('direction', "down");
    $c.util.getComponent('dma_ListXhrReq').set('method', "updateEditClassOrdNo");
    $c.util.getComponent('txt_listDiv').setValue(await scwin.tx_fn_Down_xhr());
    /* sdd-asis-lifecycle:end */
};
